    # Create enhanced client and fraud service\n    enhanced_client = EnhancedShopifyClient(\n        shop_domain=store.shop_domain,\n        access_token=store.access_token\n    )\n    \n    fraud_service = FraudAnalysisService(db, store, user)\n    \n    # Test order\n    order_name = input(\"Enter order name to test (e.g., PW110446): \").strip()\n    if not order_name:\n        print(\"❌ No order name provided\")\n        return\n    \n    print(f\"\\n📦 Testing MCP delivery tracking for order: {order_name}\")\n    print(\"=\" * 55)\n    \n    # Test 1: Enhanced GraphQL query\n    print(\"\\n1️⃣ Testing Enhanced GraphQL Query...\")\n    print(\"-\" * 45)\n    \n    try:\n        enhanced_order_data = await enhanced_client.get_order_with_comprehensive_delivery_data(order_name)\n        \n        if enhanced_order_data:\n            print(\"✅ Enhanced order data retrieved successfully\")\n            \n            # Show order basic info\n            order_info = enhanced_order_data.get('order_info', {})\n            print(f\"   Order ID: {order_info.get('id')}\")\n            print(f\"   Created: {order_info.get('created_at')}\")\n            print(f\"   Total: ${order_info.get('total_price')}\")\n            print(f\"   Status: {order_info.get('fulfillment_status')}\")\n            \n            # Show customer info\n            customer = enhanced_order_data.get('customer', {})\n            if customer:\n                print(f\"   Customer: {customer.get('firstName', '')} {customer.get('lastName', '')}\")\n                print(f\"   Total Orders: {customer.get('numberOfOrders', 0)}\")\n                \n                customer_orders = customer.get('orders', {}).get('edges', [])\n                print(f\"   Order History Available: {len(customer_orders)} orders\")\n            \n            # Show fulfillments\n            fulfillments = enhanced_order_data.get('fulfillments', [])\n            print(f\"   Current Order Fulfillments: {len(fulfillments)}\")\n   